const fs = require('node:fs');
const path = require('node:path');
const ts = require('typescript');
const out = '/tmp/pdos-build-start-owned-tests';
fs.mkdirSync(out, { recursive: true });
for (const name of ['build-start-view.ts', 'build-start-view.test.ts']) {
  const source = fs.readFileSync(`src/lib/${name}`, 'utf8');
  const compiled = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020, esModuleInterop: true, isolatedModules: true }, fileName: name });
  fs.writeFileSync(path.join(out, name.replace(/\.ts$/, '.js')), compiled.outputText);
}
